preview=(agent/'editorial/S6_SERIES_PUBLISH_I_residual_batch8_preview.tex').read_text()
def block(t,label):
    pos=t.index('\\label{'+label+'}')
    ms=list(re.finditer(r'\\begin\{(theorem|proposition|lemma|remark|corollary)\}',t[:pos]))
    m=ms[-1]; kind=m.group(1)
    end=t.index('\\end{'+kind+'}',pos)+len('\\end{'+kind+'}')
    if kind!='remark': end=t.index('\\end{proof}',end)+len('\\end{proof}')
    return t[m.start():end]
